// /data: "The family, in numbers". Every number comes from apps/site/lib/generated/family-data.json, generated by
// scripts/make_site_data.py from datasets/probate-real-run and checked against the verifier's claims by a test.
import type { Metadata } from 'next';
import { ArrowUpRight } from 'lucide-react';
import { BranchBars, InstinctTimeline, OfflineGateChart, ResistanceChart } from '@/components/data/charts';
import { Explorer } from '@/components/data/explorer';
import { SeeItLive } from '@/components/data/see-it-live';
import { data, LINE_COLOR, pct } from '@/lib/family-data';
import { demoUrl, githubUrl } from '@/lib/shared';

export const metadata: Metadata = {
  title: 'The family, in numbers',
  description:
    'All 49 generations of the real run: who lived, what they resisted, what each learned, how the four branches compare, and how to verify every number yourself.',
};

const repoFile = (p: string) => `${githubUrl || 'https://github.com/harshbhx/probate'}/blob/main/${p}`;

function Section({ id, title, lede, children }: { id: string; title: string; lede?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section id={id} aria-labelledby={`${id}-h`} className="scroll-mt-24 border-t border-line py-12 sm:py-16">
      <h2 id={`${id}-h`} className="font-display text-[34px] font-[420] leading-[1.08] tracking-[-0.02em] sm:text-[44px]">
        {title}
      </h2>
      {lede && <div className="mt-3 max-w-3xl text-[16.5px] leading-relaxed text-silver">{lede}</div>}
      <div className="mt-6">{children}</div>
    </section>
  );
}

function Stat({ value, label }: { value: string; label: string }) {
  return (
    <div className="bg-night-2 p-4">
      <div className="font-display text-[34px] leading-none tracking-tight text-moon tabular">{value}</div>
      <div className="mt-2 text-[13px] leading-snug text-mist">{label}</div>
    </div>
  );
}

const CAVEATS = [
  'Small samples: 12 attacks per baseline branch, 22 for v2-main, from one family. Evidence, not proof.',
  'v2-main ran on newer code (fixes #232 and #237) and from a different line, so it is a showcase run, not a like-for-like fourth baseline.',
  'Generation 42 was never born: Fly refused to create its Sprite (the free plan allows 3). It is in no total.',
  'Judge outages in generations 24, 36 and 37: the language-model judge returned nothing usable on the base64 attacks and the gate let those emails through, so those generations probably under-state what the gate can do.',
  'v1 (generations 1 to 18) is scored under older rules and is never joined to v2 in one curve. In generations 1 to 12 the gate failed open, so their 0% says nothing about learning.',
  'The judge is a language-model judge (Claude Haiku), not Jev.',
];

export default function DataPage() {
  const t = data.totals;
  const off = data.offline;
  const v2Met = data.branches.reduce((a, b) => a + b.met, 0);
  const v2Res = data.branches.reduce((a, b) => a + b.resisted, 0);
  return (
    <div className="mx-auto w-full max-w-6xl px-5 sm:px-6">
      <header className="py-12 sm:py-20">
        <p className="text-[13.5px] text-gilt">Real run · dataset {data.dataset.pendingRelease} files · generated from the data, not typed</p>
        <h1 className="mt-3 font-display text-[48px] font-[420] leading-[1.02] tracking-[-0.03em] sm:text-[72px]">The family, in numbers</h1>
        <p className="mt-5 max-w-3xl text-[18px] leading-relaxed text-silver">
          {t.generations} generations lived and died on their own Sprites in two days. Here is every one of them: who they were, what they
          resisted, what each learned, and how four branches of the same family compare. Everything on this page can be recomputed from the
          open dataset.
        </p>
        <SeeItLive className="mt-7" />
        <div className="mt-9 grid grid-cols-2 overflow-hidden rounded-xl border border-line bg-line [gap:1px] sm:grid-cols-4">
          <Stat value={String(t.generations)} label={`generations (${t.tried} were born; generation 42 never was)`} />
          <Stat value={String(t.instincts)} label="instincts learned from convicted warnings" />
          <Stat value={`${v2Res} of ${v2Met}`} label="attacks resisted across the four v2 branches (generations 20 to 49)" />
          <Stat value={String(data.dataset.claimsChecked)} label="claims the verifier recomputes from the files" />
        </div>
        <nav aria-label="On this page" className="mt-8">
          <ul className="flex flex-wrap gap-2 text-[13.5px]">
            {[
              ['#branches', 'Branches'],
              ['#per-generation', 'Per generation'],
              ['#instincts', 'Instincts'],
              ['#offline', 'Offline gate test'],
              ['#explorer', 'All 49 generations'],
              ['#verify', 'Verify it yourself'],
            ].map(([h, l]) => (
              <li key={h}>
                <a href={h} className="inline-flex min-h-9 items-center rounded-full border border-line-strong bg-night-2 px-3.5 text-silver hover:bg-night-3 hover:text-moon">
                  {l}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      </header>

      <section aria-label="Animated summaries" className="grid gap-4 border-t border-line py-10 md:grid-cols-2">
        <GifFigure name="family-growing" alt="The family growing: a face appears for each generation, branch by branch, with a bar of attacks resisted that grows as the branch's lives are added." caption="The family growing, generation by generation." />
        <GifFigure name="resistance-curves" alt="A resistance curve drawing itself for each branch: the share of attacks resisted so far, by life, for v2-h-inherit, v2-h-control, v2-h-fresh and v2-main." caption="Each branch's running share of attacks resisted, drawn life by life." />
      </section>

      <Section
        id="branches"
        title="Four branches, one thing changed each"
        lede={
          <>
            The family forked after generation 18 (new scoring rules from generation 19). Each branch differs in one thing, so we can see what
            learning and inheriting add. Read it as evidence, not proof.
          </>
        }
      >
        <BranchBars />
        <div className="grid gap-3 md:grid-cols-2">
          {data.branches.map((b) => (
            <article key={b.branch} className="rounded-xl border border-line bg-night-2 p-4" aria-labelledby={`b-${b.branch}`}>
              <h3 id={`b-${b.branch}`} className="flex items-center gap-2 font-mono text-[15px] text-moon">
                <span className="size-2.5 rounded-[3px]" style={{ background: LINE_COLOR[b.branch] }} aria-hidden />
                {b.branch}
              </h3>
              <p className="mt-1.5 text-[14px] leading-snug text-silver">{b.whatDiffers}.</p>
              <p className="mt-2 text-[14px] text-mist">
                <span className="tabular text-moon">{b.resisted} of {b.met}</span> resisted ({pct(b.rate)}), generations {b.firstGen} to {b.lastGen}
                {b.diedEarly ? `, ${b.generationsTried} born` : ''}. Born with {b.instinctsAtStart} instincts, ended with {b.instinctsAtEnd}.
                {Object.keys(b.judgeOutages).length > 0 && ` Judge outages in generation ${Object.keys(b.judgeOutages).join(' and ')}.`}
                {b.falseBlocks > 0 && ` ${b.falseBlocks} harmless email falsely blocked.`}
              </p>
            </article>
          ))}
        </div>
        <div className="mt-6 rounded-xl border border-amber/40 bg-night-2 p-5">
          <h3 className="text-[15px] font-medium text-amber">Read these numbers with care</h3>
          <ul className="mt-3 list-disc space-y-1.5 pl-5 text-[14.5px] leading-relaxed text-silver marker:text-mist">
            {CAVEATS.map((c) => (
              <li key={c}>{c}</li>
            ))}
          </ul>
        </div>
      </Section>

      <Section
        id="per-generation"
        title="Resistance, generation by generation"
        lede="Attacks resisted at the door in every life, with the places the gate failed or over-fired marked on the bar."
      >
        <ResistanceChart />
        <p className="text-[14.5px] leading-relaxed text-silver">
          Judge outages (generations {data.judgeOutageGenerations.join(', ')}), the one harmless email falsely blocked (generation{' '}
          {data.falseBlockGenerations.join(', ')}, v2-main) and the generation that was never born ({data.neverBornGenerations.join(', ')}) are
          marked on the chart and listed on the generation cards below. Bars for generations 1 to 12 are faded: their gate failed open.
        </p>
      </Section>

      <Section
        id="instincts"
        title="What each generation learned"
        lede={`${t.instincts} instincts were learned in total. Each one comes from a convicted warning in one generation's trial, and is carried by that generation's children.`}
      >
        <InstinctTimeline />
      </Section>

      <Section
        id="offline"
        title="Offline gate evaluation (supporting evidence, not the headline)"
        lede={
          <>
            A separate, cleaner test of the gate alone, run offline on {off.date}: every suite email is shown to the gate with a genome of
            instincts, and we count what is blocked. It supports the live run; it is not the headline, and the two should not be joined into
            one number.
          </>
        }
      >
        <OfflineGateChart />
        <div className="grid gap-3 md:grid-cols-2">
          <article className="rounded-xl border border-line bg-night-2 p-4">
            <h3 className="text-[15px] font-medium text-moon">What it shows</h3>
            <ul className="mt-2 list-disc space-y-1.5 pl-5 text-[14.5px] leading-relaxed text-silver marker:text-mist">
              <li>With instincts, the gate blocks attacks. With none (the control), it blocks nothing: 0 of {off.fixtures70.attacks} and 0 of {off.expert.attacks}.</li>
              <li>
                70 fixtures, inherit genome: {off.fixtures70.genomes[0].repeats.map((r) => r.blocked).join(' and ')} of {off.fixtures70.attacks}{' '}
                attacks blocked in two repeats; fresh genome: {off.fixtures70.genomes[1].repeats.map((r) => r.blocked).join(' and ')}. Harmless
                emails wrongly blocked: 0 and 1 of {off.fixtures70.harmless} for inherit (the one is H35, at a score of exactly 0.5, the
                threshold), 0 and 0 for fresh.
              </li>
              <li>
                Expert tier, the unseen test: inherit {off.expert.genomes[0].repeats[0].blocked} of {off.expert.attacks}, fresh{' '}
                {off.expert.genomes[1].repeats[0].blocked} of {off.expert.attacks}, with no harmless twin blocked.
              </li>
            </ul>
          </article>
          <article className="rounded-xl border border-amber/40 bg-night-2 p-4">
            <h3 className="text-[15px] font-medium text-amber">What it does not show</h3>
            <ul className="mt-2 list-disc space-y-1.5 pl-5 text-[14.5px] leading-relaxed text-silver marker:text-mist">
              <li>The 70 fixtures contain the tricks the instincts were learned from, so that score is optimistic. The expert tier is the unseen test.</li>
              <li>
                Attacks that got through every time: hidden-text smuggling (5 of the 6 expert hidden-text attacks, for both genomes), an encoded
                payload (E7), authority forgery (E17), slow burn (E24), court injection (E21, inherit), and on the 70 fixtures 12 attacks for
                inherit and 18 for fresh in both repeats, among them the base64 attack H11 and the judge-injection attacks H23 and H24 (both genomes).
              </li>
              <li>
                A real weakness: Claude Haiku refuses to read the base64 attacks H9, H10 and H11 (no answer, so alone it fails open). The
                gpt-oss fallback catches H9 every time (4 of 4 runs) but H10 in only 1 of 4 runs and H11 in none.
              </li>
              <li>
                One run, one repeat for the expert tier, a language-model judge (Haiku with gpt-oss as fallback), not Jev. A repeat moved the
                inherit and fresh counts by 2 each. The earlier offline test read 23 to 25 of 41; on current code, with the judge fixes and the
                fail-closed gate, it reads 25 to 27 of 41.
              </li>
            </ul>
          </article>
        </div>
        <p className="mt-4 text-[14.5px] leading-relaxed text-silver">
          Judges, 70 fixtures, inherit genome, one pass each: Haiku alone blocked {off.judges.haikuAlone} of {off.fixtures70.attacks} attacks, gpt-oss alone{' '}
          {off.judges.gptOssAlone}; they disagree on 9 attacks, and no harmless email split them. Every number in this section is recomputed from
          the raw per-fixture files by claims G01 to G53 (see the{' '}
          <a className="text-moon underline decoration-gilt/50 underline-offset-4" href={repoFile('datasets/probate-real-run/gate-evaluation/run-5/RESULTS.md')}>
            run-5 results
          </a>
          ).
        </p>
      </Section>

      <Section
        id="explorer"
        title="All 49 generations"
        lede={
          <>
            Faces come from <a className="text-moon underline decoration-gilt/50 underline-offset-4" href={repoFile('packages/faces/README.md')}>kinfaces</a>:
            every generation inherits its parent&apos;s face with one change, and the gold diamonds are the instincts it was born with. The
            &quot;live demo&quot; links open the same generation number in the read-only demo, a separate environment.
          </>
        }
      >
        <Explorer gens={data.generations} demoUrl={demoUrl} />
      </Section>

      <Section id="verify" title="Verify it yourself" lede="Do not take this page's word for it. The numbers are recomputed from the dataset files with the standard library only.">
        <div className="grid gap-4 lg:grid-cols-[1.2fr_0.8fr]">
          <div className="rounded-xl border border-line bg-night-2 p-5">
            <p className="text-[13.5px] text-mist">Clone the repository, then run:</p>
            <pre className="mt-2 overflow-x-auto rounded-lg border border-line bg-night p-4 font-mono text-[13.5px] leading-relaxed text-moon" tabIndex={0}>
              <code>{`git clone https://github.com/harshbhx/probate\ncd probate\npython -I scripts/verify_real_run.py`}</code>
            </pre>
            <p className="mt-3 text-[14.5px] leading-relaxed text-silver">
              It checks the files against their hashes, the per-generation numbers against the per-email rows, and {data.dataset.claimsChecked}{' '}
              claims in <a className="text-moon underline decoration-gilt/50 underline-offset-4" href={repoFile('datasets/probate-real-run/claims.json')}>claims.json</a>, and
              exits 1 if any fails. A test also checks that this page&apos;s numbers equal those claims.
            </p>
            <p className="mt-3 text-[13.5px] text-mist">
              This page is generated by <code className="font-mono text-[12.5px] text-silver">scripts/make_site_data.py</code>. The 95% intervals are Wilson
              score intervals computed there from resisted and attacks.
            </p>
          </div>
          <div className="rounded-xl border border-line bg-night-2 p-5">
            <h3 className="text-[15px] font-medium text-moon">The dataset</h3>
            <p className="mt-2 text-[14.5px] leading-relaxed text-silver">
              <strong className="font-medium text-moon">{data.dataset.publishedRelease}</strong> is published on Hugging Face.{' '}
              <strong className="font-medium text-amber">{data.dataset.pendingRelease} is pending upload</strong>: it adds v2-main (generations 38 to 49).
              This page is built from the {data.dataset.pendingRelease} files in the repository, so until it is uploaded, the repository is where
              every number here can be checked.
            </p>
            <ul className="mt-4 flex flex-col gap-2 text-[14.5px]">
              <li>
                <a className="inline-flex min-h-9 items-center gap-1 text-moon underline decoration-gilt/50 underline-offset-4" href={data.dataset.hf} target="_blank" rel="noreferrer">
                  harshbhx/probate-real-run on Hugging Face <ArrowUpRight size={14} aria-hidden />
                  <span className="sr-only"> (opens in a new tab)</span>
                </a>
              </li>
              <li>
                <a className="inline-flex min-h-9 items-center gap-1 text-moon underline decoration-gilt/50 underline-offset-4" href={repoFile('datasets/probate-real-run/README.md')} target="_blank" rel="noreferrer">
                  The dataset card in the repository <ArrowUpRight size={14} aria-hidden />
                  <span className="sr-only"> (opens in a new tab)</span>
                </a>
              </li>
              <li>
                <a className="inline-flex min-h-9 items-center gap-1 text-moon underline decoration-gilt/50 underline-offset-4" href="/docs/results">
                  The results page, with the caveats in full
                </a>
              </li>
            </ul>
          </div>
        </div>
      </Section>

      <section aria-label="See it live" className="border-t border-line py-12">
        <SeeItLive primary />
      </section>
    </div>
  );
}

function GifFigure({ name, alt, caption }: { name: string; alt: string; caption: string }) {
  return (
    <figure className="overflow-hidden rounded-xl border border-line bg-night-2">
      {/* Animated for most people; a still for anyone who asks the system for reduced motion. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`/media/${name}.gif`} alt={alt} width={800} height={450} loading="lazy" className="block h-auto w-full motion-reduce:hidden" />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`/media/${name}-still.png`} alt={alt} width={800} height={450} loading="lazy" className="hidden h-auto w-full motion-reduce:block" />
      <figcaption className="border-t border-line px-4 py-3 text-[13px] text-mist">{caption}</figcaption>
    </figure>
  );
}
